import * as T from './vendor/three.module.js';
import {groundedBody} from './grounding.js';
export function gesture(bear,kind,t,side=0){const fade=Math.min(1,t*3,Math.max(0,(kind==='highfive'?3:5)-t)*3),wave=Math.sin(t*5);bear.body.position.y=groundedBody([0,0])+Math.max(0,Math.sin(t*6))*(kind==='dance'?.045:.012)*fade;bear.body.rotation.set(kind==='highfive'?.14*fade:0,0,kind==='dance'?wave*.10*fade:0);bear.legs.forEach((g,i)=>g.rotation.set(kind==='dance'?Math.sin(t*6+i*Math.PI)*.16*fade:0,0,0));bear.arms.forEach((g,i)=>g.rotation.set(kind==='highfive'?(i===side?-2.05*fade:-.15*fade):(-.35+Math.sin(t*5+i*Math.PI)*.24)*fade,0,kind==='highfive'?0:(i?-.35:.35)*fade));}
export function faceBear(bear,other,room){const p=bear.avatar.position,up=room?new T.Vector3(0,1,0):p.clone().normalize(),forward=other.clone().sub(p);forward.addScaledVector(up,-forward.dot(up));if(forward.lengthSq()<1e-8)return;forward.normalize();const right=new T.Vector3().crossVectors(up,forward).normalize();bear.avatar.quaternion.setFromRotationMatrix(new T.Matrix4().makeBasis(right,up,forward));}
